// ============================================================
// SUB: ALL PROJECT WARNINGS
// Receives: { projectConfigs, ceoBriefingStatus }
// Splits into 11 items, loops each project
// ============================================================

const input = $input.first().json;
const projectConfigs = input.projectConfigs || [];

if (!projectConfigs.length) {
  return [{ json: { error: 'No project configs received', status: 'skipped' } }];
}

// Return each project as separate item — will be processed one by one
return projectConfigs.map(p => ({ json: p }));

// ============================================================
// Check project metrics vs benchmarks
// Builds warning message if any red/yellow detected
// ============================================================

const projectConfig = $('Loop One Project at a Time').first().json;
const sheetRows = $input.all();

const col = (item, idx) => {
  const obj = item.json || item;
  const keys = Object.keys(obj);
  return obj[keys[idx]];
};
const fmt = (n) => {
  n = parseFloat(n) || 0;
  if (Math.abs(n) >= 1e9) return (n/1e9).toFixed(2) + ' tỷ';
  if (Math.abs(n) >= 1e6) return Math.round(n/1e6) + ' tr';
  return (n*100).toFixed(1)+'%' // fallback for ratios
};
const fmtSmart = (name, n) => {
  n = parseFloat(n) || 0;
  const isRatio = name.toLowerCase().includes('tỷ lệ') || name.toLowerCase().includes('margin') || name.toLowerCase().includes('rate') || name.toLowerCase().includes('cp/ds') || name.toLowerCase().includes('take rate');
  if (isRatio) return (n*100).toFixed(1)+'%';
  if (Math.abs(n) >= 1e9) return (n/1e9).toFixed(2)+' tỷ';
  if (Math.abs(n) >= 1e6) return Math.round(n/1e6)+' tr';
  return n.toLocaleString('vi-VN');
};

// Column mapping: T04 MTD = col 5, yesterday dynamic
const today = new Date();
const yesterdayColIdx = 5 + today.getDate() - 1; // Apr1=col6, Apr23=col28

// Extract all metrics
const metricsData = {};
sheetRows.forEach(item => {
  const name = (col(item, 0) || '').toString().trim();
  const benchmark = (col(item, 1) || '').toString().trim();
  if (!name || name.length < 3 || /^[A-Z]\./i.test(name)) return;
  metricsData[name] = {
    benchmark,
    mtd: parseFloat(col(item, 5)) || 0,
    yesterday: parseFloat(col(item, yesterdayColIdx)) || 0,
    hasBenchmark: benchmark.includes('🔴') || benchmark.includes('✅')
  };
});

// Key metrics to check (ones with benchmarks)
const keyMetrics = [
  'Tổng GMV', 'GMV Livestream', 'CP/DS Live', 'GMV Ads',
  'Ads/DS (Take Rate)', '★ LỢI NHUẬN RÒNG', 'Net Profit Margin',
  'Tỷ lệ hủy đơn', 'Tỷ lệ hoàn', 'DS từ Booking', 'Affiliate Video GMV'
];

const metricsForClaude = keyMetrics
  .filter(k => metricsData[k])
  .map(k => ({
    name: k,
    benchmark: metricsData[k].benchmark,
    mtd_fmt: fmtSmart(k, metricsData[k].mtd),
    yesterday_fmt: fmtSmart(k, metricsData[k].yesterday),
    mtd_raw: metricsData[k].mtd,
    yesterday_raw: metricsData[k].yesterday
  }));

const hasData = metricsForClaude.length > 0;

// Build Claude prompt for this project
const systemPrompt = `Bạn là AI phân tích dự án ${projectConfig.name} của Hecatech (thị trường: ${projectConfig.market}).
Phân tích chỉ số so với benchmark và tạo daily warning message cho team.
Viết tiếng Việt, súc tích, tập trung hành động. Dưới 220 từ.`;

const today_str = today.toLocaleDateString('vi-VN');
const userPrompt = `Dự án: ${projectConfig.name} | Ngày: ${today_str}

Chỉ số MTD và hôm qua (với benchmark):
${JSON.stringify(metricsForClaude, null, 2)}

Tạo warning message theo format:

⚡ ${projectConfig.name.toUpperCase()} — ${today_str}

[Nếu có chỉ số vượt ngưỡng đỏ trong benchmark:]
🔴 VẤN ĐỀ CẦN XỬ LÝ:
• [Tên]: [giá trị] (benchmark: [ngưỡng]) → [hành động cụ thể]

[Nếu có chỉ số vàng:]
🟡 THEO DÕI: [tóm tắt ngắn]

✅ TÍCH CỰC: [1-2 điểm tốt]

📋 TODO: [1-2 việc ưu tiên nhất hôm nay]

Nếu mọi chỉ số đều OK: chỉ viết "✅ ${projectConfig.name} ổn định — không có cảnh báo." (1 dòng)`;

return [{
  json: {
    projectConfig,
    hasData,
    metricsForClaude,
    claudeRequest: {
      model: 'claude-sonnet-4-6',
      max_tokens: 600,
      system: systemPrompt,
      messages: [{ role: 'user', content: userPrompt }]
    }
  }
}];

const claudeResponse = $input.first().json;
const warningText = claudeResponse?.content?.[0]?.text || '⚠️ Lỗi phân tích.';
const projectConfig = $('Check Benchmarks and Build Warning').first().json.projectConfig;

return [{
  json: {
    webhookUrl: projectConfig.webhook,
    larkMessage: { msg_type: 'text', content: { text: warningText } }
  }
}];
